shell_commands:
cat << 'EOF' >> src/orchestration/chatOrchestrator.test.ts

  it('drives a stub provider through a rejected tool call followed by a corrected retry ([validated by: drives a stub provider through a rejected tool call followed by a corrected retry])', async () => {
    let secondRoundMessages: Message[] | undefined;
    let callCount = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        if (callCount++ === 0) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {wrong: 'yes'}}};
          yield {type: 'stop', stopReason: 'tool_use'};
        } else {
          secondRoundMessages = params.messages;
          yield {type: 'text', text: 'ok, I fixed it'};
          yield {type: 'stop', stopReason: 'end_turn'};
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'looks things up',
        inputSchema: {type: 'object', required: ['q'], properties: {q: {type: 'string'}}},
      },
      async () => ({result: 'found it'})
    );

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const result = await orchestrator.processMessage(createSession('ask'));

    expect(result).toBe('ok, I fixed it');
    expect(secondRoundMessages).toBeDefined();

    const lastMessage = secondRoundMessages![secondRoundMessages!.length - 1] as ToolResultMessage;
    expect(lastMessage.role).toBe('user');
    expect(lastMessage.content[0].type).toBe('tool_result');
    expect(lastMessage.content[0].content).toContain('Invalid input for tool lookup: data/input must have required property \'q\'');
  });
});
EOF
